e = html.escape
def kind(v):
    v=v.lower()
    if 'thesis' in v: return 'thesis'
    if 'arxiv' in v: return 'preprint'
    if 'workshop' in v or 'symposium' in v or 'bridge' in v: return 'workshop'
    if any(k in v for k in ['journal','transactions','jmlr','tmlr','ijrr','jirs','foundations and trends','handbook','ijars','international journal']): return 'journal'
    return 'conference'
def authors(a):
    return e(a).replace("A. Geramifard", "<b>A. Geramifard</b>")
out=[]; years=sorted({p[0] for p in P}, reverse=True); kinds={}
for y in years:
    n=sum(1 for p in P if p[0]==y)
    out.append(f'<div class="year" data-year="{y}">\n  <h2>{y}</h2>\n  <ul class="pubs">')
    for (yy,a,t,v,links,notes) in P:
        if yy!=y: continue
        k=kind(v); kinds[k]=kinds.get(k,0)+1
        first=next(iter(links.values()),None)
        title=f'<a href="{e(first)}" target="_blank" rel="noopener">{e(t)}</a>' if first else e(t)
        rest=list(links.items())[1:]
        tags="".join(f'<a href="{e(u)}" target="_blank" rel="noopener">{e(l)}</a>' for l,u in rest)
        tags+="".join(f'<span class="pill {kk}">{e(n_)}</span>' for n_,kk in notes)
        tagrow=f'\n      <div class="tags">{tags}</div>' if tags else ''
        out.append(f'    <li class="pub" data-kind="{k}">\n      <div class="title">{title}</div>\n      <div class="authors">{authors(a)}</div>\n      <div class="venue"><em>{e(v)}</em>, {y}</div>{tagrow}\n    </li>')
    out.append('  </ul>\n</div>')
body="\n".join(out)
tmpl=open(__import__("os").path.join(__import__("os").path.dirname(__file__),"publications.tmpl.html")).read()
open(__import__("os").path.join(__import__("os").path.dirname(__file__),"..","publications.html"),"w").write(tmpl.replace("<!--PUBS-->",body).replace("<!--COUNT-->",str(len(P))))
print(len(P),"entries,",len(years),"years",kinds)
